const pvpOpponentId=(pvp,id)=>id===pvp.attackerId?pvp.defenderId:pvp.attackerId;
export const legalPvpEffectTypes=(effect,phase,role,siegeOnly=false)=>Object.keys(effect||{}).filter(type=>{if(['bannerGloryArmy','gemPouch','sunAmulet','darkAmulet'].includes(type))return true;if(type==='swordJustice')return role==='attack'&&phase==='melee';if(role==='block')return ['block','iceBlock','fireBlock','coldfireBlock','multiBlock'].includes(type);if(phase==='ranged')return siegeOnly?['siege','iceSiege','fireSiege','coldfireSiege'].includes(type):RANGED_POINT_KEYS.includes(type);return [...MELEE_POINT_KEYS,...RANGED_POINT_KEYS].includes(type);});
