  state.levelUpContext=null;state.phase='action';const immediateExtraTurn=Boolean(context.immediateExtraTurn),hex=currentHex(state),target=handLimit(state)+(context.handLimitBonus||0);state.endTurnContext=null;if(!roundAnnouncement&&!context.skipDraw&&state.player.hand.length<target)draw(state,target-state.player.hand.length);
  if(!roundAnnouncement&&hex?.site==='glade')state.mana.push(state.time==='day'?'gold':'black');
  state.turn++;
  if(state.multiplayer){
    if(state.scenarioEndTurnsRemaining!==null){if(!state.scenarioFinalTurnsStarted)state.scenarioFinalTurnsStarted=true;else{state.scenarioEndTurnsRemaining--;if(state.scenarioEndTurnsRemaining<=0){state.status='won';state.scoring=calculateScore(state);log(state,'Final turns are complete. The conquest has ended.');return state;}}}
    if(immediateExtraTurn){state.player.timeBentTurn=Boolean(context.timeBending);state.player.atTurnStart=true;state.player.emptyHandPassAllowed=!state.player.hand.length&&Boolean(state.player.deck.length);grantSustainedManaClaims(state);log(state,context.timeBending?`${state.player.name} bends time and immediately takes another turn.`:`${state.player.name} takes the extra turn granted by ${state.player.tactic?.name}.`);checkpointTurn(state);return state;}
    if(state.roundEndTurnsRemaining!==null&&!roundAnnouncement){state.roundEndTurnsRemaining--;if(state.roundEndTurnsRemaining<=0){state.player.nextRoundHandBonus=(state.player.nextRoundHandBonus||0)+(context.handLimitBonus||0);return nextRound(state);}}
    state.player.timeBentTurn=false;const currentIndex=state.turnOrder.indexOf(state.activePlayerId);let nextIndex=(currentIndex+1)%state.turnOrder.length,nextPlayer=null,guard=0;while(guard<=state.turnOrder.length){const candidateId=state.turnOrder[nextIndex];if(candidateId==='dummy'){if(state.roundEndTurnsRemaining===null)takeDummyTurn(state);nextIndex=(nextIndex+1)%state.turnOrder.length;guard++;continue;}nextPlayer=playerById(state,candidateId);if(nextPlayer?.skipNextTurn){nextPlayer.skipNextTurn=false;nextPlayer.roundOrderFaceDown=false;nextPlayer.plunderedBetweenTurns=false;log(state,`${nextPlayer.name} skips the turn already spent fully attending PvP or a joint assault.`);if(state.scenarioEndTurnsRemaining!==null){state.scenarioEndTurnsRemaining--;if(state.scenarioEndTurnsRemaining<=0){state.status='won';state.scoring=calculateScore(state);log(state,'Final turns are complete. The conquest has ended.');return state;}}if(state.roundEndTurnsRemaining!==null){state.roundEndTurnsRemaining--;if(state.roundEndTurnsRemaining<=0)return nextRound(state);}nextIndex=(nextIndex+1)%state.turnOrder.length;guard++;continue;}break;}state.activePlayerId=state.turnOrder[nextIndex];bindPlayerState(state,state.activePlayerId);state.player.plunderedBetweenTurns=false;state.player.atTurnStart=true;state.player.emptyHandPassAllowed=!state.player.hand.length&&Boolean(state.player.deck.length);state.points=freshPoints();state.mana=[];state.sourceTaken=false;resetTurnBonuses(state);grantSustainedManaClaims(state);log(state,`${state.player.name}'s turn begins.`);checkpointTurn(state);return state;
  }
  if(immediateExtraTurn){state.player.timeBentTurn=Boolean(context.timeBending);state.player.atTurnStart=true;state.player.emptyHandPassAllowed=!state.player.hand.length&&Boolean(state.player.deck.length);grantSustainedManaClaims(state);log(state,context.timeBending?'Time bends; another turn begins immediately.':`Turn ${state.turn} begins immediately.`);checkpointTurn(state);return state;}state.player.timeBentTurn=false;state.player.atTurnStart=true;state.player.emptyHandPassAllowed=!state.player.hand.length&&Boolean(state.player.deck.length);grantSustainedManaClaims(state);log(state,`Turn ${state.turn} begins.`);checkpointTurn(state); return state;
